    if ($_.Name -ne 'env') { $settingsObj[$_.Name] = $_.Value }
}
$settingsObj['env'] = $envObj
if (-not $settingsObj.ContainsKey('$schema')) {
    $settingsObj['$schema'] = 'https://json.schemastore.org/claude-code-settings.json'
